const normalize=text=>String(text??'').toLowerCase().replaceAll('ё','е').replace(/[^\p{L}\p{N} ]/gu,' ').replace(/\s+/g,' ').trim();
function score(value,key){
  return terms[key].reduce((points,word)=>points+(value.includes(' '+word+' ')?word.split(' ').length:0),0);
}
function classify(text){
  const value=' '+normalize(text)+' ';
  if(score(value,'wrong'))return {key:'wrong'};
  const temporary=/не (?:звоните|перезванивайте) (?:сейчас|до )|пока не (?:звоните|перезванивайте)/.test(value)&&
    !(/больше|вообще|номер|из базы/.test(value));
  if(!temporary&&score(value,'stop'))return {key:'stop'};
  if(score(value,'urgent'))return {key:'urgent'};
  if(score(value,'privacy')||/откуда.*(?:номер|телефон)|где (?:вы )?(?:взяли|нашли).*(?:номер|телефон)/.test(value)){
    return {key:'privacy',preferred:/где|откуда/.test(value)?'source':'verify'};
  }
  if(score(value,'quality'))return {key:'quality',preferred:/отслоилось|отвалилось|скололось|грубил|слезло/.test(value)?'review':'listen'};
  if(score(value,'self'))return {key:'self'};
  if(score(value,'callback')||temporary)return {key:'time',preferred:'callback'};
  if(score(value,'missed'))return {key:'missed'};
  if(score(value,'stylist'))return {key:'stylist'};
  if(/давайте запишемся|хочу записаться|запишите меня|да подберите/.test(value)&&!(/не хочу записаться|не записывайте/.test(value)))return {key:'interest'};
  if(score(value,'provider'))return {key:'provider',preferred:/если хотите расскажу|могу рассказать|могу объяснить/.test(value)?'alternative':'respect'};
  if(/сколько (?:это )?стоит|какая цена|сориентируйте по цене|по какой цене/.test(value))return {key:'price',preferred:'scope'};
  if(/какая гарантия|есть ли гарантия|сколько длится|что входит|как долго длится|сколько займет/.test(value))return {key:'details'};
  if(/не буду делать|не хочу делать|не хочу сейчас|мне не интересно/.test(value))return {key:'not_now'};
  if(/не могу говорить|неудобно говорить|сейчас не могу|за рулем|на встрече/.test(value))return {key:'time',preferred:'callback'};
  if(/в другом городе|не в ижевске|уехал[а]? из города/.test(value))return {key:'location',preferred:'one-visit'};
  let key='other',highest=0;
  for(const candidate of ['price','time','location','not_now','unsure','interest']){
    const found=score(value,candidate);
    if(found>highest){key=candidate;highest=found;}
  }
  return {key};
}

export const identifyObjection=text=>classify(text).key;
export function recommend(text,feedback=[],branch='',override=''){
  const contextual=classify(text);
  const key=Object.hasOwn(objections,override)&&!['stop','wrong','urgent'].includes(contextual.key)?override:contextual.key;
  const preferred=key===contextual.key?contextual.preferred:null;
  const objection=objections[key];
  const rated=feedback.filter(vote=>vote.branch===branch&&vote.objection===key);
  const priority=item=>Number(item.id===preferred||key==='provider'&&!preferred&&item.id==='respect');
  const options=objection.options.map(item=>{
    const votes=rated.filter(vote=>vote.option===item.id);
    const useful=votes.filter(vote=>vote.helpful).length;
    return {...item,votes:votes.length,score:(useful+1)/(votes.length+2)};
  }).sort((a,b)=>priority(b)-priority(a)||b.score-a.score);
  return {key,label:objection.label,options,votes:rated.length};
}

